import type { MouseEventHandler } from 'react'
import React from 'react'
import type { LinkProps } from './Link'
import Link from './Link'

export default {
  title: 'Components/Link',
  component: Link,
  argTypes: {
    onClick: {
      control: { type: 'select' },
      options: ['None', 'Click handler'],
    },
  },
  args: {
    href: 'http://www.example.com/',
  },
}

const onClick: MouseEventHandler<HTMLAnchorElement> = (event): void => {
  event.preventDefault()
  alert('Link was clicked!')
}

function Template(args: LinkProps): JSX.Element {
  const clickHandler =
    ((args.onClick as unknown) as string) === 'Click handler'
      ? onClick
      : undefined

  return (
    <div className="m-6">
      <Link {...args} onClick={clickHandler}>
        Click me!
      </Link>
    </div>
  )
}

export const Default = {
  render: Template,
}
